pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address[] calldata tos, uint[] calldata vals) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == vals.length);

        Acceptor a = new Acceptor();

        bool ok;
        try c.transfer(from, address(a), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!ok) {
            assertTrue(address(c).balance >= 0);
        } else {
            bool ret;
            try c.transfer(from, address(a), tos, vals) returns (bool r) {
                ret = r;
            } catch {
                assertTrue(false);
            }
            assertTrue(ret == true);
        }
    }
}

